using System;using UnityEngine;using UnityEngine.UI;using UnityEditor;using UnityEditor.SceneManagement;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckKeepaway.Editor {
public static class KeepawayRegressionAuthoring {
 public static void UpgradeBoth(){foreach(var path in new[]{KeepawayAuthoring.Scene,KeepawayChaosAuthoring.CabScene}){EditorSceneManager.OpenScene(path);Install(UnityEngine.Object.FindAnyObjectByType<KeepawayMatch>());EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());}AssetDatabase.SaveAssets();}
 public static void Install(KeepawayMatch m){foreach(var ramp in m.chaosField.ramps)ramp.GetComponent<MeshCollider>().convex=true;foreach(var label in m.identities)label.GetComponent<Renderer>().enabled=false;var old=m.menus.transform.Find("Projected Keepaway names");if(old!=null)UnityEngine.Object.DestroyImmediate(old.gameObject);var root=SportsUIAuthoring.Rect("Projected Keepaway names",m.menus.transform,Vector2.zero,Vector2.zero).GetComponent<RectTransform>();root.anchorMin=Vector2.zero;root.anchorMax=Vector2.one;root.offsetMin=root.offsetMax=Vector2.zero;var names=m.GetComponent<KeepawayNameplates>()??m.gameObject.AddComponent<KeepawayNameplates>();names.match=m;names.panels=new RectTransform[4];names.plates=new RectTransform[16];names.captions=new TMPro.TMP_Text[16];for(int v=0;v<4;v++){var panel=SportsUIAuthoring.Rect("Names viewport "+v,root,Vector2.zero,Vector2.zero).GetComponent<RectTransform>();names.panels[v]=panel;for(int i=0;i<4;i++){int id=v*4+i;var plate=SportsUIAuthoring.Rect("Projected participant "+i,panel,new Vector2(240,30),Vector2.zero).GetComponent<RectTransform>();plate.anchorMin=plate.anchorMax=Vector2.zero;plate.pivot=new Vector2(.5f,.5f);var backing=plate.gameObject.AddComponent<Image>();backing.color=new Color(.006f,.016f,.023f,.84f);backing.raycastTarget=false;names.plates[id]=plate;names.captions[id]=SportsUIAuthoring.Text("Readable name",plate,"",new Vector2(230,28),Vector2.zero,22);names.captions[id].enableWordWrapping=false;names.captions[id].overflowMode=TMPro.TextOverflowModes.Ellipsis;names.captions[id].fontSizeMin=18;names.captions[id].fontSizeMax=22;plate.gameObject.SetActive(false);}panel.gameObject.SetActive(false);}foreach(var view in m.cabViews)if(view.cabSteering==null||view.cabSteering.wheel==null)throw new Exception("Keepaway actual cab steering binding missing");EditorUtility.SetDirty(m);}
 public static void Validate(){var m=UnityEngine.Object.FindAnyObjectByType<KeepawayMatch>();if(m.GetComponent<KeepawayNameplates>()?.plates.Length!=16)throw new Exception("Keepaway projected nameplates missing");foreach(var t in m.identities)if(t.GetComponent<Renderer>().enabled)throw new Exception("Keepaway world labels must not enter cabs");foreach(var ramp in m.chaosField.ramps)if(!ramp.GetComponent<MeshCollider>().convex)throw new Exception("Keepaway wedge queries require convex collision");Debug.Log("KEEP_REGRESSION_SAVED_VALIDATED projected names, proper ramp queries, real cab wheel");}
}
}
